update public.learning_paths
set
  title = 'Educational Psychology',
  goal = 'Educational Psychology',
  summary = 'Educational Psychology studies how learners develop, think, remember, regulate, participate, and thrive in educational settings. The course covers child development, classroom management, assessment, inclusive practice, learning sciences, educational technology, research inquiry, and graduate psychology foundations.',
  data = $edpsjson${"slug": "educational-psychology", "title": "Educational Psychology", "description": "Educational Psychology studies how learners develop, think, remember, regulate, participate, and thrive in educational settings. The course covers child development, classroom management, assessment, inclusive practice, learning sciences, educational technology, research inquiry, and graduate psychology foundations.", "topics": [{"id": "d85409e1-2907-4a8b-bf96-182306e0f272", "type": "topic", "title": "Educational Psychology as a Science of Learning and Teaching", "description": "Students learn how psychological science informs teaching, learning environments, learner development, and evidence-based educational decisions.", "children": [{"id": "a8ff2bec-d13e-427b-81b8-6fbd020d5759", "type": "subtopic", "title": "Field orientation", "children": [{"id": "4ceefe7c-28c3-44a2-b93b-320cfec03a5e", "type": "concept", "title": "Learning, development, motivation, instruction, assessment, and context"}, {"id": "82074e34-9e56-4e24-8518-1923ba799ab4", "type": "concept", "title": "Teacher judgment informed by evidence"}, {"id": "7ea86c44-15c3-4dfa-bfa7-4397e11f2c93", "type": "concept", "title": "Limits of one-size-fits-all teaching advice"}], "description": "The point is to see educational psychology as a bridge between research and classroom decision-making."}, {"id": "6f5209c2-506b-4d43-8c3a-a8bd8e0d5a34", "type": "subtopic", "title": "Evidence and application", "children": [{"id": "a3e3aec6-34a5-45dc-b586-405f98958b91", "type": "concept", "title": "Laboratory, classroom, qualitative, and mixed-method evidence"}, {"id": "17043d3b-89cd-42ca-bb99-f5f42e9e1b7e", "type": "concept", "title": "Research-to-practice gaps"}, {"id": "c9915b1e-e3f5-47ba-aa82-63ab66bd1733", "type": "concept", "title": "Implementation, adaptation, and local context"}], "description": "Students learn to translate research into practice without oversimplifying it."}, {"id": "2e8c6c46-d81a-46fb-8ece-2adf3d1048da", "type": "subtopic", "title": "Professional stance", "children": [{"id": "9511cf62-919a-4a66-86ca-573f47d3bdc9", "type": "concept", "title": "Learner dignity and strengths"}, {"id": "76c6e6d8-8614-4816-90ef-49c9382098b9", "type": "concept", "title": "Equity, access, and belonging"}, {"id": "78f2a6ca-6316-4362-97a8-bee0de457999", "type": "concept", "title": "Reflective practice and continuous improvement"}], "description": "Educational psychology supports humane, rigorous, and equitable teaching."}]}, {"id": "e02a3b66-8f0f-400d-ae1c-561e27c691aa", "type": "topic", "title": "Learner Development: Cognitive, Social, Emotional, and Identity Growth", "description": "This module connects developmental theory to classroom expectations, supports, relationships, and instruction.", "children": [{"id": "9f9d87ee-f6fa-4e13-a74b-ef1b2aa692e2", "type": "subtopic", "title": "Developmental theories", "children": [{"id": "56a6d786-5e35-470c-bccc-ed8d151d798f", "type": "concept", "title": "Piaget, Vygotsky, Erikson, Bronfenbrenner, and contemporary views"}, {"id": "93d47b54-9101-4747-ac2d-50566322b67c", "type": "concept", "title": "Stage models, continuities, and cautions"}, {"id": "cb1a5ee2-eb05-4e19-b6c5-086f61dda942", "type": "concept", "title": "Developmentally appropriate practice"}], "description": "Students use developmental theory to interpret learner needs and classroom behavior."}, {"id": "74b1ec7d-7e75-47a2-943e-71bccd1deab5", "type": "subtopic", "title": "Child and adolescent development", "children": [{"id": "b6a9f839-27e3-40bc-a1c8-d19a47d8f607", "type": "concept", "title": "Cognitive, language, moral, social, and emotional development"}, {"id": "125c1bf9-4975-4d76-9522-817426156759", "type": "concept", "title": "Identity, peers, family, and school transitions"}, {"id": "3113472a-e505-4edc-84c6-d3e794d008d2", "type": "concept", "title": "Risk, resilience, and protective relationships"}], "description": "The gist is to connect age, context, and maturation to teaching choices."}, {"id": "e885d744-659b-4f11-b712-fc76d4b12848", "type": "subtopic", "title": "Development and instruction", "children": [{"id": "c7b6f3ae-5278-429c-9e05-d76335f1998b", "type": "concept", "title": "Zone of proximal development"}, {"id": "7406b4fa-7293-44f8-b97a-b9282fc2dcac", "type": "concept", "title": "Scaffolding and guided participation"}, {"id": "1b775402-feae-4fbe-9868-b748ca70779c", "type": "concept", "title": "Strengths-based developmental observation"}], "description": "Teachers use development to design supports, not to cap expectations."}]}, {"id": "6892eb8b-2cb7-4c54-bcaf-e12ae93b48a6", "type": "topic", "title": "Behaviorist, Social Learning, and Applied Behavior Perspectives", "description": "Students learn how reinforcement, modeling, feedback, and behavior supports shape classroom learning and participation.", "children": [{"id": "dde4ce2f-a6f4-4ccd-84df-b3f8d3f2a87e", "type": "subtopic", "title": "Conditioning and reinforcement", "children": [{"id": "789b829a-9cf4-4fa3-b168-91818ee3fd81", "type": "concept", "title": "Classical and operant conditioning"}, {"id": "e189fbe6-b80f-4ef3-b57f-a26320bddac7", "type": "concept", "title": "Reinforcement schedules, shaping, prompting, and fading"}, {"id": "4f80d299-ad20-4f6e-9db3-ec08aa217659", "type": "concept", "title": "Punishment cautions and unintended effects"}], "description": "Students learn how consequences and cues influence behavior and learning routines."}, {"id": "94f4bb8e-da0c-4bd7-9ca3-b76b05524ebf", "type": "subtopic", "title": "Social learning", "children": [{"id": "7c9751cc-a5d3-465b-80fb-2e4cc7f85275", "type": "concept", "title": "Bandura, observational learning, and self-efficacy"}, {"id": "c0864d6d-6f95-46d8-9523-1637b7f58a5c", "type": "concept", "title": "Teacher modeling and peer modeling"}, {"id": "34df27eb-facb-4788-af50-d316945fd5f6", "type": "concept", "title": "Media, identity, and vicarious reinforcement"}], "description": "Learners acquire behaviors, norms, and strategies through models and social context."}, {"id": "9020fd79-9d10-4779-8982-9aa5451b4a2e", "type": "subtopic", "title": "Positive behavior supports", "children": [{"id": "9346b271-9704-48f4-9904-9d6ddbc935b9", "type": "concept", "title": "PBIS, functional behavior assessment, and antecedent supports"}, {"id": "f7b4dedf-d4c1-4a7a-b0d3-0a3f39735939", "type": "concept", "title": "Behavior as communication"}, {"id": "7dc5e82c-ff17-483c-b8f5-d7ac5567568e", "type": "concept", "title": "Data-based intervention and progress monitoring"}], "description": "Behavior support is most ethical when proactive, instructional, and relationship-centered."}]}, {"id": "e040bac9-c003-456c-9cc8-35f9858f931d", "type": "topic", "title": "Cognitive Learning, Memory, Attention, and Information Processing", "description": "This topic explains how learners encode, retrieve, transfer, and manage information under real classroom conditions.", "children": [{"id": "ac542300-0b72-47ba-8246-cd6d4c6c4565", "type": "subtopic", "title": "Attention and working memory", "children": [{"id": "2fb49913-3239-42b1-83de-f475b68b2055", "type": "concept", "title": "Selective attention and distraction"}, {"id": "0529704c-d480-44ec-9c0e-70233fe669ac", "type": "concept", "title": "Cognitive load"}, {"id": "15cc2e2a-4f19-485b-b28e-e6e13ea7b377", "type": "concept", "title": "Chunking, modeling, and worked examples"}], "description": "Learning design must respect limited attentional and working-memory capacity."}, {"id": "d0dc4bb6-3503-49b9-8cd1-3f18d6894cd1", "type": "subtopic", "title": "Memory and durable learning", "children": [{"id": "b0140ba9-4ec2-43ef-bec5-fbe78be34154", "type": "concept", "title": "Encoding, retrieval, spacing, interleaving, and elaboration"}, {"id": "0ebca984-ddc1-4ece-8cd4-51c5bc0134a5", "type": "concept", "title": "Desirable difficulties"}, {"id": "95312097-c7f5-4624-88c8-97d83d39ada7", "type": "concept", "title": "Misconceptions and forgetting"}], "description": "Students learn why some strategies produce lasting understanding and others only feel effective."}, {"id": "7669f12a-d43d-46e5-8cd2-a5a7169ced98", "type": "subtopic", "title": "Transfer and understanding", "children": [{"id": "550240a5-61de-465c-be54-3ba7dcd390f7", "type": "concept", "title": "Near and far transfer"}, {"id": "6aa8372b-b08c-430d-9ca8-89b27364f165", "type": "concept", "title": "Conceptual change"}, {"id": "3a4b1b7f-0fc4-485f-984c-9103c592eab4", "type": "concept", "title": "Schema building and analogical reasoning"}], "description": "The goal is for learners to use knowledge flexibly beyond the original lesson."}]}, {"id": "525d2bc6-d280-435b-898d-6500673d81c2", "type": "topic", "title": "Constructivist, Sociocultural, and Learning Sciences Perspectives", "description": "Students study learning as active meaning-making shaped by language, tools, culture, collaboration, and context.", "children": [{"id": "082fb08e-faa3-49b5-a1c5-5762076df589", "type": "subtopic", "title": "Constructivist learning", "children": [{"id": "938c000d-f3c2-47e2-be22-6b7b91405d2c", "type": "concept", "title": "Prior knowledge and misconceptions"}, {"id": "de510a9e-98a7-4e18-b01c-650bc3ec36e8", "type": "concept", "title": "Inquiry, problem-based learning, and project-based learning"}, {"id": "c4a6e21a-130e-4d17-801d-229230ce1389", "type": "concept", "title": "Conceptual conflict and guided discovery"}], "description": "Students learn how learners actively build meaning from prior knowledge and experience."}, {"id": "c8c70080-ea0d-40e0-ac71-59d322feeba8", "type": "subtopic", "title": "Sociocultural learning", "children": [{"id": "d9c77de4-197b-41e9-b314-80584a39e7b6", "type": "concept", "title": "Vygotsky, apprenticeship, and communities of practice"}, {"id": "aa445ec4-6fb8-4a13-a523-a2cf95192b60", "type": "concept", "title": "Discourse, collaboration, and classroom talk"}, {"id": "66c464a3-e1a4-4150-af59-d3a1e9611ac3", "type": "concept", "title": "Funds of knowledge and culturally situated learning"}], "description": "Learning is shaped by language, tools, relationships, and cultural participation."}, {"id": "e7cfdb71-d6e7-458a-96df-301bfa183984", "type": "subtopic", "title": "Learning sciences", "children": [{"id": "6ad99e89-5215-4083-90ec-9b4ff591fa72", "type": "concept", "title": "How People Learn principles"}, {"id": "05a7514a-8bc7-4b29-9205-1fe511034e88", "type": "concept", "title": "Formal and informal learning"}, {"id": "80629af3-44c3-4212-976d-db66ea6dff7e", "type": "concept", "title": "Design-based research and learning environments"}], "description": "Students connect research on cognition, design, technology, and environments."}]}, {"id": "5681dbc6-02ef-48c8-936c-8ae1c4ede36d", "type": "topic", "title": "Motivation, Engagement, Mindsets, Identity, and Learner Agency", "description": "This module examines why students choose, persist, avoid, or disengage from learning tasks.", "children": [{"id": "fe5fc919-7716-4d8f-b54f-5e3064acc7cf", "type": "subtopic", "title": "Motivation theories", "children": [{"id": "40872372-c7e8-498d-92f8-48ea04007501", "type": "concept", "title": "Expectancy-value, self-determination, attribution, goal orientation, and interest"}, {"id": "4ebce5bd-35d2-4669-835a-f55e38ba35e4", "type": "concept", "title": "Autonomy, competence, relatedness, and relevance"}, {"id": "141570dc-e9f2-4ef3-830d-7ca9e94c2adf", "type": "concept", "title": "Intrinsic and extrinsic motivation"}], "description": "Students compare theories that explain effort, persistence, and task choice."}, {"id": "eae93c03-dcea-4ec4-89fe-debcb0cbe353", "type": "subtopic", "title": "Beliefs and identity", "children": [{"id": "ae549d5d-456f-4d69-b735-28a8a47438a0", "type": "concept", "title": "Mindset with evidence-based cautions"}, {"id": "2353d4fa-ec2c-4e79-b6e2-b0bb6f36ade9", "type": "concept", "title": "Academic identity and stereotype threat"}, {"id": "834df3d5-b868-407b-bcc3-2b5ee9993c92", "type": "concept", "title": "Self-efficacy, possible selves, and belonging"}], "description": "Learners' beliefs about ability and belonging shape engagement."}, {"id": "bf0dbf39-3972-4c8a-9d39-65ef8b37f62b", "type": "subtopic", "title": "Engagement design", "children": [{"id": "e3837565-42ab-4d69-8f21-de5d8c4f74dd", "type": "concept", "title": "Choice, challenge, feedback, and purpose"}, {"id": "b47f22db-ab23-404b-8146-2f8081bd41d0", "type": "concept", "title": "Culturally meaningful tasks"}, {"id": "68da6fc0-d119-4344-af78-f4aabda8597e", "type": "concept", "title": "Avoidance, anxiety, boredom, and disengagement"}], "description": "Teachers can design tasks that invite agency and persistence."}]}, {"id": "63d8f9df-cc7d-4515-aa2a-96c917d35ea9", "type": "topic", "title": "Self-Regulated Learning, Metacognition, Executive Function, and Study Strategies", "description": "Students learn how learners plan, monitor, evaluate, and improve their own learning.", "children": [{"id": "0dad38e0-af9f-4cdd-8549-fe37ee41dd3e", "type": "subtopic", "title": "Metacognition", "children": [{"id": "4a723642-7b99-46a2-a132-6a1ed2e386b3", "type": "concept", "title": "Planning, monitoring, evaluating, and adjusting"}, {"id": "acc47d29-410f-4bea-a098-3d6200817dd9", "type": "concept", "title": "Calibration and illusion of knowing"}, {"id": "2135f106-fa33-4e30-bf90-d92f2d545b2b", "type": "concept", "title": "Think-alouds, reflection, and self-questioning"}], "description": "Students learn how learners think about and monitor their own understanding."}, {"id": "27c64985-f34a-4f23-97bc-284b9e87c743", "type": "subtopic", "title": "Executive function", "children": [{"id": "0e4e60e9-c41a-407b-888a-ea9393090325", "type": "concept", "title": "Inhibition, working memory, flexibility, planning, and organization"}, {"id": "46d8b7c1-3822-4ca9-af3d-f08ca1f57f21", "type": "concept", "title": "Emotion regulation and stress"}, {"id": "9a6d2b51-2608-4855-8cce-37d8d9e237e7", "type": "concept", "title": "Classroom supports and gradual release"}], "description": "Self-regulation depends on cognitive and emotional skills that develop over time."}, {"id": "fd2cc68c-bdc5-4651-bd04-ef0f4c334283", "type": "subtopic", "title": "Study strategies", "children": [{"id": "b5590fc7-d107-475d-ba0f-72778d96042d", "type": "concept", "title": "Retrieval practice, spacing, elaboration, interleaving, and dual coding"}, {"id": "687de9d2-8b4c-4513-8545-dd3e19dcc82f", "type": "concept", "title": "Note-taking, summarizing, and concept mapping"}, {"id": "6da72859-c1c2-402a-bc1b-aa4ca7d61748", "type": "concept", "title": "Teaching students how to study, not just what to study"}], "description": "Students learn strategies that are supported by cognitive science."}]}, {"id": "6bbc5597-b857-44fd-a675-b69369343814", "type": "topic", "title": "Individual Differences, Neurodiversity, Exceptional Learners, and Inclusive Practice", "description": "This topic centers learner variability, disability, giftedness, accessibility, and inclusive instructional design.", "children": [{"id": "6a9076aa-b35f-42e7-83c1-f88d183b63d8", "type": "subtopic", "title": "Learner variability", "children": [{"id": "339a850d-00fa-4750-a464-86e8c6171479", "type": "concept", "title": "Readiness, interests, language, prior knowledge, and pace"}, {"id": "48591958-b5eb-4a01-9f9a-9a06fc11ef46", "type": "concept", "title": "Giftedness, twice-exceptionality, and learning differences"}, {"id": "a3bd2656-ec87-40c8-8d00-b6b16e9785a9", "type": "concept", "title": "Avoiding deficit-only interpretations"}], "description": "Students learn to design for varied strengths, needs, histories, and profiles."}, {"id": "bfa2be4f-edb6-47f7-8461-9b790c187b7d", "type": "subtopic", "title": "Disability and neurodiversity", "children": [{"id": "00bf7777-e8b8-4bbd-80df-3b954bfed6b2", "type": "concept", "title": "ADHD, autism, dyslexia, intellectual disability, sensory differences, and emotional-behavioral needs"}, {"id": "27583a21-f2bd-4ea8-905a-16074ce7b31b", "type": "concept", "title": "IEPs, 504 plans, accommodations, and assistive technology"}, {"id": "e2726719-4b54-4f6b-9ad7-97642d9897c4", "type": "concept", "title": "Universal Design for Learning"}], "description": "Inclusive practice treats accessibility as central to learning design."}, {"id": "73fd54f6-2006-4e0f-b138-35c40793e3cd", "type": "subtopic", "title": "MTSS and intervention", "children": [{"id": "1c4115ac-ddac-435a-aaeb-64a6c52d8ae7", "type": "concept", "title": "RTI/MTSS tiers"}, {"id": "4037f048-a0a6-4e34-ad7a-8a157704508f", "type": "concept", "title": "Progress monitoring and data-based decision-making"}, {"id": "0b3645f0-735d-4911-83da-c3d2630e1a3a", "type": "concept", "title": "Collaboration with specialists, families, and paraprofessionals"}], "description": "Students learn how tiered supports connect instruction, data, and collaboration."}]}, {"id": "1aa51962-4296-432a-8bc6-45a5c6cd84de", "type": "topic", "title": "Culture, Language, Family, Community, and Culturally Sustaining Pedagogy", "description": "Students learn how culture, language, home knowledge, and community context shape learning and belonging.", "children": [{"id": "5f8828ee-9b5e-4a07-935f-091908feeac6", "type": "subtopic", "title": "Culture and learning", "children": [{"id": "1c879f6f-55bb-4af2-8283-6e877f215f8a", "type": "concept", "title": "Culturally responsive and culturally sustaining pedagogy"}, {"id": "f89e8077-f714-49d2-886c-8e75866e37a5", "type": "concept", "title": "Funds of knowledge"}, {"id": "340fa8b3-07f4-42e4-9c06-877389c8dcc8", "type": "concept", "title": "Avoiding stereotypes and cultural mismatch"}], "description": "Culture shapes participation, communication, expectations, and meaning."}, {"id": "60e69d37-7f23-4d11-a9b8-4df134c9ee31", "type": "subtopic", "title": "Language and multilingual learners", "children": [{"id": "a9b0cae3-5fbf-4a42-896a-e36e35ca05a3", "type": "concept", "title": "Academic language and vocabulary"}, {"id": "762690d1-990d-49fe-93c3-72129b29b392", "type": "concept", "title": "Bilingualism, translanguaging, and language brokering"}, {"id": "5884d06e-ad13-4c49-ae4a-16c2bf8d8dd9", "type": "concept", "title": "Assessment and instruction for multilingual learners"}], "description": "Students learn how language development affects access to curriculum."}, {"id": "6d9038f1-3ae6-4c6d-a580-79a631b52b97", "type": "subtopic", "title": "Families and communities", "children": [{"id": "4e9a00ec-bfe5-4bf9-b8cb-a1cb1ee06516", "type": "concept", "title": "Family communication and trust"}, {"id": "14c3d285-11cb-410e-817b-db92fd09f7bf", "type": "concept", "title": "Community context and home-school connections"}, {"id": "bfbaf250-2838-4a46-bf00-ed9a57e4461e", "type": "concept", "title": "Trauma, migration, poverty, and resilience"}], "description": "Effective teaching treats families as partners and communities as knowledge sources."}]}, {"id": "8079a8bb-3854-4cf5-a7e4-432968f6ac90", "type": "topic", "title": "Classroom Climate, Relationships, Management, and Trauma-Informed Community Building", "description": "This module links safety, routines, relationships, belonging, and behavior supports to learning.", "children": [{"id": "dcdb025d-2f01-4319-b692-3b8b1caa654f", "type": "subtopic", "title": "Relationships and belonging", "children": [{"id": "80a88dd7-a6a8-4976-9081-d40fa1a9a003", "type": "concept", "title": "Teacher-student relationships"}, {"id": "51635dcb-2ed6-4980-8a2e-975bec60bdef", "type": "concept", "title": "Peer belonging and classroom norms"}, {"id": "e259e8b0-8fbb-40f4-b61d-2f2277663f00", "type": "concept", "title": "Respect, dignity, and psychological safety"}], "description": "Learning improves when classrooms are emotionally safe and relationally strong."}, {"id": "cd28f68c-b83d-4284-aeec-48f090fdba91", "type": "subtopic", "title": "Classroom management", "children": [{"id": "2838ac29-7430-48ca-91dd-350c80ac86f1", "type": "concept", "title": "Procedures, transitions, and routines"}, {"id": "17754362-1a42-4d33-86ea-542fcc64757f", "type": "concept", "title": "Expectations, accountability, and restorative responses"}, {"id": "8df16536-2435-42b9-ab0b-4e38e8126fd4", "type": "concept", "title": "Preventive design and active supervision"}], "description": "Management is the design of routines, expectations, attention, and support."}, {"id": "a311aed7-1993-4790-a4ff-11c47cf9888e", "type": "subtopic", "title": "Trauma-informed practice", "children": [{"id": "45cd3709-c58e-4cc8-892a-4e78a04ef845", "type": "concept", "title": "Regulation, safety, predictability, and choice"}, {"id": "4364298d-796d-4c0d-a060-50dd4f512ea2", "type": "concept", "title": "Adverse experiences and protective relationships"}, {"id": "57f3e645-64a1-4f13-bb98-866d5d729eb2", "type": "concept", "title": "Teacher wellbeing and secondary stress"}], "description": "Students learn how stress and trauma affect learning without reducing students to trauma histories."}]}, {"id": "136561f6-d5fd-4940-92df-ba160d6037ed", "type": "topic", "title": "Instructional Design, Scaffolding, Feedback, Practice, and Transfer", "description": "Students learn how to design instruction that supports understanding, fluency, application, and durable transfer.", "children": [{"id": "a0b386e7-15d6-4795-8af1-d9648cd72d29", "type": "subtopic", "title": "Instructional design", "children": [{"id": "5c1b9cfc-da4b-43b4-8ffc-4117609e04ff", "type": "concept", "title": "Backward design and learning goals"}, {"id": "0a9cead2-782d-4b02-8ec2-231d045ad364", "type": "concept", "title": "Modeling, guided practice, independent practice"}, {"id": "c4b11a34-8ec9-47f9-9a4e-91a4537ac210", "type": "concept", "title": "Sequencing, examples, and nonexamples"}], "description": "Teachers align objectives, evidence, instruction, and learner needs."}, {"id": "eef9b895-1c78-40c3-8247-91584673217b", "type": "subtopic", "title": "Scaffolding and feedback", "children": [{"id": "e126d1f0-01f4-41b2-aaab-0e9b89f58b68", "type": "concept", "title": "Hints, prompts, worked examples, and gradual release"}, {"id": "9e2b51ff-81ab-457f-8c96-e913b8fcc283", "type": "concept", "title": "Feedback timing, specificity, and actionability"}, {"id": "3226232e-1c49-498c-827c-871e330906ab", "type": "concept", "title": "Peer feedback and revision cycles"}], "description": "Students learn how support and feedback move learners toward independence."}, {"id": "fca8e56e-42d4-4acc-886f-0e5ab9da8087", "type": "subtopic", "title": "Practice and transfer", "children": [{"id": "bef11cae-e1f5-4573-b0f8-e87f81d775fd", "type": "concept", "title": "Deliberate practice and automaticity"}, {"id": "81a6ca2c-65c9-4c43-b95c-516f92b406f5", "type": "concept", "title": "Application, problem solving, and authentic tasks"}, {"id": "1901ed36-4568-47aa-9c21-43e3a7e101da", "type": "concept", "title": "Transfer across subjects, settings, and time"}], "description": "Practice should build fluency and flexible understanding."}]}, {"id": "2d5cbb3e-7acf-4cc8-ad61-d4796b7fa7cf", "type": "topic", "title": "Assessment, Feedback, Rubrics, Data Use, and Fair Evaluation", "description": "This topic connects assessment to learning goals, formative feedback, equity, accommodations, and improvement decisions.", "children": [{"id": "968d3ceb-2a0a-4e5c-b021-62872094b92d", "type": "subtopic", "title": "Assessment purposes", "children": [{"id": "ab77dc7c-d612-4053-942f-6057d7270009", "type": "concept", "title": "Formative, summative, diagnostic, and performance assessment"}, {"id": "edf1c072-e438-435e-8910-1c377501da43", "type": "concept", "title": "Learning targets and success criteria"}, {"id": "10aa83a2-db04-48ed-809f-e211fb6a8528", "type": "concept", "title": "Student self-assessment and portfolios"}], "description": "Students learn to distinguish assessment for learning, of learning, and as learning."}, {"id": "59288ff3-ffcf-4f44-8e3a-1239c75b31f6", "type": "subtopic", "title": "Fair assessment design", "children": [{"id": "beeb45b9-b050-4225-8502-7b902b2b585c", "type": "concept", "title": "Rubrics, scoring criteria, and reliability"}, {"id": "ac614f67-4fcb-44ba-910d-a4e40d6f214d", "type": "concept", "title": "Bias, fairness, accommodations, and accessibility"}, {"id": "45d821c1-1657-4fe8-86c3-c53632c43d08", "type": "concept", "title": "Multilingual and disability-inclusive evaluation"}], "description": "Assessment should measure intended learning while reducing irrelevant barriers."}, {"id": "482c59e1-1781-4cb0-87b6-a0ce473ccef3", "type": "subtopic", "title": "Data use", "children": [{"id": "e30de2f3-3e09-4d6f-acf0-da113ded06e2", "type": "concept", "title": "Progress monitoring and item analysis"}, {"id": "ef3c3b40-35d4-4b0a-835e-79d5dcf4898a", "type": "concept", "title": "Feedback loops and reteaching decisions"}, {"id": "c799053c-dc0f-460b-ac28-e591aad8bdd0", "type": "concept", "title": "Reporting to students, families, and teams"}], "description": "Data should improve instruction rather than label students simplistically."}]}, {"id": "464ab645-a17f-4062-92cc-0bdf389c7d16", "type": "topic", "title": "Educational Technology, Digital Learning, Accessibility, and AI in Education", "description": "Students evaluate technology through learning science, accessibility, digital citizenship, and ethical implementation.", "children": [{"id": "35e37124-f65f-48f2-999d-1bf0d95781c6", "type": "subtopic", "title": "Technology integration", "children": [{"id": "282ac5ec-3e76-4a0f-ad55-3f4ad77c8358", "type": "concept", "title": "Pedagogy-first selection"}, {"id": "6ec04544-1a87-4bb3-9632-f24dc5962c38", "type": "concept", "title": "SAMR/TPACK as planning heuristics"}, {"id": "aff3b38d-4098-413b-a5ff-218f0bf69db2", "type": "concept", "title": "Learning management systems and digital workflow"}], "description": "Students evaluate technology by whether it improves learning, access, and participation."}, {"id": "b04a6c4c-9668-43b2-987f-b4eb1822f143", "type": "subtopic", "title": "Digital learning design", "children": [{"id": "7b0ad979-9b31-4a9e-b92c-4e12dd5a4d09", "type": "concept", "title": "Multimedia learning and cognitive load"}, {"